def _ledger(data, revision_first, discounted, refunds):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        if revision_first:
            key = (event.get("revision", 0), pos)
        else:
            key = (event.get("sequence", 0), event.get("revision", 0), pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), mode)
        base = net if discounted else raw
        tax = _round(base * event.get("tax_bp", 0), mode)
        total = net + tax
        if refunds and event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_06(data):
    from itertools import product

    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    choices = []
    for name in names:
        choices.append([None] + list(packages[name]))
    best_vector = None
    best = None

    for assignment in product(*choices):
        selected = {name: row for name, row in zip(names, assignment)
                    if row is not None}
        valid = True
        for name, bounds in data["roots"].items():
            if name not in selected or not bounds[0] <= selected[name]["version"] <= bounds[1]:
                valid = False
                break
        if not valid:
            continue
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        for name, row in selected.items():
            version = row["version"]
            if version in blocked.get(name, []) or (name in pins and version != pins[name]):
                valid = False
                break
        if not valid:
            continue

        edges = {name: [] for name in selected}
        for name, row in selected.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if target not in selected:
                    valid = False
                    break
                version = selected[target]["version"]
                if not dep["min"] <= version <= dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(data["roots"])
        while stack and valid:
            name = stack.pop()
            if name in reachable:
                continue
            if name not in selected:
                valid = False
                break
            reachable.add(name)
            stack.extend(edges[name])
        if not valid or reachable != set(selected):
            continue

        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for target in edges[name]:
                if not visit(target):
                    return False
            state[name] = 2
            return True
        if not all(visit(name) for name in selected):
            continue

        vector = tuple(selected[name]["version"] if name in selected else -1
                       for name in names)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best = {name: row["version"] for name, row in selected.items()}

    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _component_07(data):
    from itertools import combinations

    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for subset in combinations(jobs, k):
        ids = {job["id"] for job in subset}
        if ids & blocked or not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        if any(sum(job["start"] <= t < job["end"] for job in subset) > 2
               for t in {job["start"] for job in subset}):
            continue
        value = sum(job["value"] for job in subset)
        selected = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and selected < best_ids)):
            best_value, best_ids = value, selected

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _component_08(data):
    import heapq

    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    initial_mask = bits.get(source, 0)
    start_state = (source, initial_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [edge["duration"]]
            if remaining:
                durations.append(max(2, edge["duration"] - edge.get("discount", 0)))
            for index, duration in enumerate(durations):
                new_time = depart + duration
                if new_time > data["deadline"]:
                    continue
                new_remaining = remaining - (1 if index == 1 else 0)
                dest = edge["v"]
                new_mask = mask | bits.get(dest, 0)
                new_state = (dest, new_mask, new_remaining)
                if new_time < distances.get(new_state, float("inf")):
                    distances[new_state] = new_time
                    heapq.heappush(queue, (new_time, dest, new_mask, new_remaining))
    return {"arrival": None}


